class FreshText(HTMLParser):
 def __init__(self,seed):super().__init__(convert_charrefs=False);self.out=[];self.stack=[];self.i=seed
 def handle_starttag(self,t,a):
  self.out.append('<'+t+''.join(' '+k+'="'+html.escape(v or '',quote=True)+'"' for k,v in a)+'>')
  if t not in ['br','hr','img','input','meta','link']:self.stack.append((t,dict(a).get('class','')))
 def handle_endtag(self,t):
  self.out.append('</'+t+'>')
  if self.stack:self.stack.pop()
 def handle_comment(self,d):self.out.append('<!--'+d+'-->')
 def handle_entityref(self,n):self.out.append('&'+n+';')
 def handle_charref(self,n):self.out.append('&#'+n+';')
 def handle_data(self,d):
  if not d.strip():self.out.append(d);return
  self.i+=1;cl=' '.join(x[1] for x in self.stack);tag=self.stack[-1][0]if self.stack else ''
  if re.fullmatch(r'[\d\s.,%+\-~/:억만원천명개월주배시간일원]+',d.strip()):v=d.strip()
  elif any(x in cl.split() for x in ['note','pain','by']):v=NOTES[self.i%len(NOTES)]
  elif 'vs' in cl.split():v='VS'
  elif tag=='small':v='원/월'if 'price'in cl.split()else'건'
  elif 'fig' in cl.split() or 'price' in cl.split():v=str(24+self.i%37)+'.6'
  elif 'mark' in cl.split():v=str(self.i%6+1)
  elif tag=='small':v='건'
  elif tag=='th':v=['권역','접수','완료','상태'][self.i%4]
  elif 'kick' in cl.split():v=['주간 집계','운영 구간','다음 회차','집하 기준'][self.i%4]
  elif tag=='b' and not any(x in cl.split() for x in ['name','cond']):v=str(18+self.i%57)
  else:v=NAMES[self.i%len(NAMES)]
  self.out.append(html.escape(v))
def rewrite_markup(text,name,seed):
 text=re.sub(r'data-el="[a-z0-9-]+"',lambda m:'data-el="'+name+'-'+next((x for x in sorted(ROOTS,key=len,reverse=True) if m.group().endswith('-'+x+'"')),'card')+'"',text)
 p=FreshText(seed);p.feed(text);out=''.join(p.out)
 return normalize(out,name)

